"""The public scorecard (docs/scorecard.md) is generated by running the code, and the build fails when it drifts.

``scripts/scorecard.py`` runs the golden question set, the held-out and training triage sets and the self-test in a
neutral environment (no user configuration, no KUBE_NOOB_* variable, a throwaway data directory), counts rules,
playbooks and knowledge from the code, and quotes the community-question tables of
docs/evals/supported-technologies.md without computing anything from them. These tests check that the committed
document matches the code, that every number is cross-checked against an independent count, that what is weak is
stated, and that the generator cannot drift (a missing heading, a changed table or a leaked setting is an error).

The engine runs once per test module (the ``data`` fixture); the other tests render synthetic data or read files.
"""

from __future__ import annotations

import copy
import importlib.util
import os
import re
import sys
from pathlib import Path
from types import ModuleType
from typing import Any

import pytest

ROOT = Path(__file__).resolve().parents[1]
DOC = ROOT / "docs" / "scorecard.md"
SUPPORTED = ROOT / "docs" / "evals" / "supported-technologies.md"


def _load() -> ModuleType:
    spec = importlib.util.spec_from_file_location("scorecard", ROOT / "scripts" / "scorecard.py")
    assert spec and spec.loader
    mod = importlib.util.module_from_spec(spec)
    sys.modules["scorecard"] = mod
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture(scope="module")
def sc() -> ModuleType:
    return _load()


@pytest.fixture(scope="module")
def data(sc: ModuleType) -> dict[str, Any]:
    return sc.collect()


# -- the committed document ------------------------------------------------------------------------------------------


def test_the_committed_scorecard_matches_the_code(sc: ModuleType, data: dict[str, Any]) -> None:
    assert DOC.read_text(encoding="utf-8") == sc.render(data), "run: python scripts/scorecard.py"


def test_check_exits_1_when_the_document_is_stale_and_0_when_it_is_current(
    sc: ModuleType,
    data: dict[str, Any],
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    out = tmp_path / "scorecard.md"
    monkeypatch.setattr(sc, "OUT", out)
    monkeypatch.setattr(sc, "collect", lambda: data)
    assert sc.main(["--check"]) == 1, "a missing document is stale"
    out.write_text("hand-edited\n", encoding="utf-8")
    assert sc.main(["--check"]) == 1
    assert "python scripts/scorecard.py" in capsys.readouterr().err
    assert sc.main([]) == 0 and out.read_text(encoding="utf-8") == sc.render(data)
    assert sc.main(["--check"]) == 0
    assert sc.main(["--bogus"]) == 2


def test_the_document_is_deterministic_and_carries_no_machine_or_time(sc: ModuleType, data: dict[str, Any]) -> None:
    text = sc.render(data)
    assert text == sc.render(copy.deepcopy(data))
    assert text.endswith("\n") and not text.endswith("\n\n")
    assert not re.search(r"/home/|/tmp/|/root/|\b20\d\d-\d\d-\d\dT\d\d:|\bUTC\b|\.venv", text)
    assert text.startswith("# Scorecard\n")


def test_the_document_passes_the_sanitiser_it_documents(sc: ModuleType, data: dict[str, Any]) -> None:
    from kube_noob import sanitize

    assert sanitize.detect(sc.render(data)) == []


# -- every number is cross-checked against an independent count ------------------------------------------------------


def test_counts_equal_an_independent_count(data: dict[str, Any]) -> None:
    from kube_noob import known_issues
    from kube_noob.audit.engine import list_rules
    from kube_noob.debug.playbooks import PLAYBOOKS
    from kube_noob.evals import selftest
    from kube_noob.knowledge.store import builtin_chunks

    counts = data["counts"]
    assert counts["rules"] == len(list_rules())
    assert counts["playbooks"] == len(PLAYBOOKS)
    assert counts["rootCauses"] == sum(len(p.root_causes) for p in PLAYBOOKS)
    chunks = builtin_chunks()
    assert counts["knowledgeSections"] == len(chunks)
    assert counts["knowledgeDocuments"] == len({c.doc_id for c in chunks})
    assert counts["reportedIssues"] == len({i.id for i in known_issues.bundled()[0]})
    assert counts["selftestCases"] == len(selftest.cases()) == data["selftest"]["total"]
    assert sum(counts["rulesByStage"].values()) == counts["rules"]


def _golden_script() -> Any:
    spec = importlib.util.spec_from_file_location("eval_golden_t", ROOT / "scripts" / "eval_golden.py")
    assert spec and spec.loader
    mod = importlib.util.module_from_spec(spec)
    sys.modules["eval_golden_t"] = mod
    spec.loader.exec_module(mod)
    return mod


def test_golden_numbers_equal_what_eval_golden_reports(sc: ModuleType, data: dict[str, Any], tmp_path: Path) -> None:
    """Recompute one technology through scripts/eval_golden.py itself and compare it with the scorecard's row."""
    from kube_noob import toolkit as tk
    from kube_noob.config import Settings

    eg = _golden_script()
    items = eg.load(ROOT / "tests" / "fixtures" / "golden")
    assert data["counts"]["goldenQuestions"] == len(items)
    assert sum(t["inScope"] + t["outOfScope"] for t in data["golden"]["technologies"]) == len(items)
    subset = [i for i in items if i["technology"] == "kubernetes"]
    kit = tk.Toolkit(Settings.model_validate({"dataDir": str(tmp_path), "learningEnabled": False}))
    again = eg.score(subset, kit)["byTechnology"]["kubernetes"]
    row = next(t for t in data["golden"]["technologies"] if t["id"] == "kubernetes")
    assert (row["inScope"], row["right"], row["outOfScope"], row["unanswered"]) == (
        again["inScope"],
        again["answeredRight"],
        again["outOfScope"],
        again["abstainedRight"],
    )
    assert row["inScopeMisses"] + row["outOfScopeMisses"] == again["misses"]


def test_triage_counts_match_the_fixtures(data: dict[str, Any]) -> None:
    import yaml

    held = yaml.safe_load((ROOT / "tests/fixtures/triage/heldout.yaml").read_text(encoding="utf-8"))
    train = yaml.safe_load((ROOT / "tests/fixtures/triage-train/train.yaml").read_text(encoding="utf-8"))
    assert data["triage"]["heldOut"]["items"] == len(held) == data["counts"]["triageHeldOut"]
    assert data["triage"]["train"]["items"] == len(train) == data["counts"]["triageTrain"]
    for part in ("heldOut", "train"):
        t = data["triage"][part]
        assert 0 <= t["causeRight"] <= t["found"] <= t["items"], part
        assert sum(k["items"] for k in t["byKind"].values()) == t["items"]
        assert sum(k["causeRight"] for k in t["byKind"].values()) == t["causeRight"]


def test_the_self_test_total_is_the_number_kube_noob_selftest_reports(data: dict[str, Any]) -> None:
    st = data["selftest"]
    assert st["total"] > 0 and st["passed"] + len(st["failures"]) == st["total"]
    assert sum(c["total"] for c in st["byCategory"].values()) == st["total"]


def _plain(text: str) -> str:
    """Undo the escapes the scorecard applies to table cells."""
    for safe, raw in (("\\|", "|"), ("\\`", "`"), ("\\*", "*"), ("&lt;", "<"), ("&gt;", ">"), ("\\\\", "\\")):
        text = text.replace(safe, raw)
    return text


# -- what is weak is stated ------------------------------------------------------------------------------------------


def test_every_golden_miss_and_misfire_is_listed_with_what_is_missing(sc: ModuleType, data: dict[str, Any]) -> None:
    text = sc.render(data)
    golden = data["golden"]
    assert len(golden["misses"]) == sum(t["inScopeMisses"] for t in golden["technologies"])
    for miss in golden["misses"]:
        assert f"`{miss['id']}`" in text and miss["gap"].split(":")[0] in text, miss["id"]
        assert " ".join(miss["gap"].split()) in _plain(text), miss["id"]
    for fire in golden["misfires"]:
        assert f"`{fire['id']}`" in text, fire["id"]
    assert not golden["regressions"], "a golden item that passed now fails: fix kube-noob, not the scorecard"


def test_the_weak_spots_section_names_the_weakest_technology_and_the_tuned_versus_held_out_gap(
    sc: ModuleType, data: dict[str, Any]
) -> None:
    text = sc.render(data)
    weak = text.split("## Where it is weak", 1)[1].split("\n## ", 1)[0]
    rows = data["golden"]["technologies"]
    worst = min(rows, key=lambda t: (t["right"] / t["inScope"], t["id"]))
    assert sc.TECHNOLOGIES.get(worst["id"], worst["id"]) in weak
    held, train = data["triage"]["heldOut"], data["triage"]["train"]
    assert f"{held['causeRight']} of {held['items']}" in weak
    assert f"{train['causeRight']} of {train['items']}" in weak
    assert "tuned" in weak and "generalis" in weak


def test_the_document_says_the_golden_score_is_a_fit_and_where_the_honest_numbers_are(
    sc: ModuleType, data: dict[str, Any]
) -> None:
    text = sc.render(data)
    reading = text.split("## How to read it", 1)[1].split("\n## ", 1)[0]
    assert "regression" in reading and "not evidence that kube-noob generalises" in reading
    assert "not evidence that kube-noob generalises" in " ".join(SUPPORTED.read_text(encoding="utf-8").split())
    assert "held-out" in reading and "community" in reading
    assert "evals/supported-technologies.md" in text, "the scorecard links the document it quotes"


def test_every_headline_number_names_the_command_that_produces_it(sc: ModuleType, data: dict[str, Any]) -> None:
    text = sc.render(data)
    table = text.split("## Headline numbers", 1)[1].split("\n## ", 1)[0]
    rows = [r for r in table.splitlines() if r.startswith("| ") and not r.startswith("| What") and "---" not in r]
    assert len(rows) >= 8
    for row in rows:
        cells = [c.strip() for c in row.strip("|").split(" | ")]
        assert len(cells) == 3 and cells[1] and re.search(r"\d", cells[1]), row
        command = cells[2]
        assert command.startswith("`") and command.endswith("`"), row
        words = command.strip("`").split()
        assert words[0] in {"python", "kube-noob"}, row
        if words[0] == "python" and words[1] != "-c":
            assert (ROOT / words[1]).is_file(), f"{words[1]} does not exist"
    assert "kube-noob selftest" in table and "scripts/eval_golden.py" in table and "scripts/eval_triage.py" in table


def test_the_commands_for_the_counts_print_the_number_in_the_table(sc: ModuleType, data: dict[str, Any]) -> None:
    """Run each ``python -c`` snippet the document prints (in this process: the modules are loaded already)."""
    import contextlib
    import io

    table = sc.render(data).split("## Headline numbers", 1)[1].split("\n## ", 1)[0]
    ran = 0
    for line in table.splitlines():
        m = re.search(r'\| `python -c "([^"]+)"` \|$', line)
        if not m:
            continue
        shown = re.search(r"\| ([\d,]+) \|", line)
        assert shown, line
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            exec(compile(m.group(1), "<document>", "exec"), {})  # noqa: S102 - the snippet the document prints
        assert out.getvalue().strip() == shown.group(1).replace(",", ""), line
        ran += 1
    assert ran >= 5


# -- the community tables are quoted, never computed -----------------------------------------------------------------


def test_the_quoted_community_tables_are_verbatim_lines_of_the_linked_document(
    sc: ModuleType, data: dict[str, Any]
) -> None:
    source = SUPPORTED.read_text(encoding="utf-8").splitlines()
    text = sc.render(data)
    quoted = [line[2:] for line in text.splitlines() if line.startswith("> |")]
    assert len(quoted) >= 12, "the two community tables are quoted"
    for line in quoted:
        assert line in source, f"not a line of docs/evals/supported-technologies.md: {line}"
    for block in data["community"]["blocks"]:
        for para in block["before"] + block["after"]:
            assert para.replace("\n", " ") in " ".join(" ".join(source).split()), para[:60]


def test_a_missing_heading_or_table_in_the_linked_document_is_an_error_not_a_silent_gap(sc: ModuleType) -> None:
    with pytest.raises(sc.ScorecardError, match="heading"):
        sc.quote_section("# Title\n\nbody\n", "## No such heading")
    with pytest.raises(sc.ScorecardError, match="table"):
        sc.quote_section("## Heading\n\nonly words here\n", "## Heading")


def test_quote_section_takes_the_paragraphs_before_the_table_the_table_and_the_paragraph_after() -> None:
    sc = _load()
    text = (
        "## Other\n\n| a |\n|---|\n| 9 |\n\n## Heading (note)\n\nFirst line\nwraps here.\n\nSecond para.\n\n"
        "| h1 | h2 |\n|---|---|\n| 1 | 2 |\n| 3 | 4 |\n\nAfter the table\nspans two lines.\n\nLater para.\n\n## Next\n"
    )
    block = sc.quote_section(text, "## Heading")
    assert block["before"] == ["First line wraps here.", "Second para."]
    assert block["table"] == ["| h1 | h2 |", "|---|---|", "| 1 | 2 |", "| 3 | 4 |"]
    assert block["after"] == ["After the table spans two lines."]
    assert block["heading"] == "Heading (note)"


# -- the neutral environment -----------------------------------------------------------------------------------------


def test_the_engine_runs_in_a_neutral_environment_and_restores_the_caller_s(
    sc: ModuleType, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from kube_noob.config import load_settings

    config = tmp_path / "config.yaml"
    config.write_text("webEnabled: true\nllm:\n  provider: anthropic\n", encoding="utf-8")
    monkeypatch.setenv("KUBE_NOOB_CONFIG", str(config))
    monkeypatch.setenv("KUBE_NOOB_LLM_PROVIDER", "anthropic")
    monkeypatch.setenv("KUBE_NOOB_MEMORY_PATHS", str(tmp_path))
    monkeypatch.setenv("XDG_CONFIG_HOME", str(tmp_path))
    before = dict(os.environ)
    assert load_settings().web_enabled is True, "the leak this test guards against exists"
    with sc.neutral_environment():
        mine = {k: v for k, v in os.environ.items() if k.startswith("KUBE_NOOB_")}
        assert set(mine) == {"KUBE_NOOB_CONFIG"} and not Path(mine["KUBE_NOOB_CONFIG"]).exists()
        settings = load_settings()
        assert settings.web_enabled is False and settings.llm.provider == "none" and settings.memory.paths == []
    assert dict(os.environ) == before


# -- rendering synthetic data ----------------------------------------------------------------------------------------


def test_render_handles_no_misses_no_failures_and_an_unknown_technology(sc: ModuleType, data: dict[str, Any]) -> None:
    quiet = copy.deepcopy(data)
    quiet["golden"]["misses"] = []
    quiet["golden"]["misfires"] = []
    quiet["selftest"]["failures"] = []
    quiet["golden"]["technologies"].append(
        {
            "id": "newtech",
            "inScope": 2,
            "right": 2,
            "rightFirst": 2,
            "inScopeMisses": 0,
            "outOfScopeMisses": 0,
            "outOfScope": 1,
            "unanswered": 1,
        }
    )
    text = sc.render(quiet)
    assert "| newtech |" in text
    assert "No in-scope golden question is unanswered" in text
    assert "No out-of-scope golden question got an answer" in text


def test_text_in_a_table_cell_cannot_break_the_table_or_add_markup(sc: ModuleType, data: dict[str, Any]) -> None:
    hostile = copy.deepcopy(data)
    hostile["golden"]["misses"] = [
        {
            "id": "x-1",
            "technology": "helm",
            "question": "line one\nline | two <script>alert(1)</script> `tick` " + "w" * 300,
            "gap": "doc: a | b\nc",
            "got": ["kn:a#1", "DBG-X"],
        }
    ]
    text = sc.render(hostile)
    row = next(line for line in text.splitlines() if "`x-1`" in line)
    assert "\n" not in row and "<script>" not in row and "`tick`" not in row
    assert row.count(" | ") == 4 and row.count("\\|") == 2, row  # five cells; the two pipes stay inside a cell
    assert "w" * 200 not in row, "long questions are cut"


def test_a_regression_is_shown_in_the_document_instead_of_hidden(sc: ModuleType, data: dict[str, Any]) -> None:
    bad = copy.deepcopy(data)
    bad["golden"]["regressions"] = [{"id": "k8s-001", "status": "pass", "got": ["DBG-X"], "expect": ["DBG-Y"]}]
    bad["triage"]["heldOut"]["regressed"] = ["crashloop-0a"]
    bad["selftest"]["failures"] = [{"id": "s-1", "category": "audit", "kind": "audit", "detail": "missing: KN-S001"}]
    text = sc.render(bad)
    assert "REGRESSED" in text and "k8s-001" in text and "crashloop-0a" in text and "s-1" in text
    ok = sc.render(data)
    assert "REGRESSED" not in ok


def test_scripts_the_scorecard_runs_are_the_ones_the_document_names(sc: ModuleType) -> None:
    assert sc.GOLDEN_DIR == ROOT / "tests" / "fixtures" / "golden"
    assert sc.HELD_OUT_DIR == ROOT / "tests" / "fixtures" / "triage"
    assert sc.TRAIN_DIR == ROOT / "tests" / "fixtures" / "triage-train"
    assert sc.SUPPORTED == SUPPORTED
